  { _id: 1903, titles: [ 'The Great Train Robbery' ] },
  { _id: 1909, titles: [ 'A Corner in Wheat' ] }
]

","programmingLanguage":"JavaScript"}[  { _id: 1896, titles: [ 'The Kiss', 'The Kiss' ] },  { _id: 1903, titles: [ 'The Great Train Robbery' ] },  { _id: 1909, titles: [ 'A Corner in Wheat' ] }]Group Documents by YearThe following aggregation operation groups documents by year:{"@context":"https://schema.org","@type":"SoftwareSourceCode","codeSampleType":"code snippet","text":"db.movies.aggregate([
   { $match: { year: { $lt: 1910 } } },
   { $group: { _id: "$year", movies: { $push: "$$ROOT" } } },
   {
      $addFields: {
         totalRuntime: { $sum: "$movies.runtime" }
      }
   },
   { $sort: { _id: 1 } }
])

","programmingLanguage":"JavaScript"}db.movies.aggregate([   { $match: { year: { $lt: 1910 } } },   { $group: { _id: "$year", movies: { $push: "$$ROOT" } } },   {      $addFields: {         totalRuntime: { $sum: "$movies.runtime" }      }   },   { $sort: { _id: 1 } }])HIDE OUTPUT{"@context":"https://schema.org","@type":"SoftwareSourceCode","codeSampleType":"code snippet","text":"[
  { _id: 1896, movies: '...', totalRuntime: 2 },
  { _id: 1903, movies: '...', totalRuntime: 11 },
  { _id: 1909, movies: '...', totalRuntime: 14 }
]

","programmingLanguage":"JavaScript"}[  { _id: 1896, movies: '...', totalRuntime: 2 },  { _id: 1903, movies: '...', totalRuntime: 11 },  { _id: 1909, movies: '...', totalRuntime: 14 }]First Stage:$match filters the documents to only pass movies released before 1910 to the next stage.Second Stage:$group uses the $$ROOT system variable to group the entire documents by year.Third Stage:$addFields adds a field to the output containing the total runtime of movies for each year.NoteThe resulting documents must not exceed the BSON Document Size limit of 16 mebibytes.Fourth Stage:$sort sorts the resulting documents by _id in ascending order.The C# examples on this page use the sample_mflix database from the Atlas sample datasets. To learn how to create a free MongoDB Atlas cluster and load the sample datasets, see Get Started in the MongoDB .NET/C# Driver documentation.The following Movie class models the documents in the sample_mflix.movies collection:{"@context":"https://schema.org","@type":"SoftwareSourceCode","codeSampleType":"code snippet","text":"[BsonIgnoreExtraElements]
public class Movie
{
    [BsonId]
    public ObjectId Id { get; set; }
    [BsonElement("title")]
    public string Title { get; set; } = null!;
    [BsonElement("year")]
    public int? Year { get; set; }
    [BsonElement("runtime")]
    public int? Runtime { get; set; }
    [BsonElement("rated")]
    public string? Rated { get; set; }
    [BsonElement("metacritic")]
    public int Metacritic { get; set; }
    [BsonElement("plot")]
    public string? Plot { get; set; }
    [BsonElement("type")]
    public string? Type { get; set; }
    [BsonElement("cast")]
    public string[]? Cast { get; set; }
    [BsonElement("directors")]
    public string[]? Directors { get; set; }
    [BsonElement("writers")]
    public string[]? Writers { get; set; }
    [BsonElement("imdb")]
    public ImdbData? Imdb { get; set; }
}

","programmingLanguage":"C#"}[BsonIgnoreExtraElements]public class Movie{    [BsonId]    public ObjectId Id { get; set; }    [BsonElement("title")]    public string Title { get; set; } = null!;    [BsonElement("year")]    public int? Year { get; set; }    [BsonElement("runtime")]    public int? Runtime { get; set; }    [BsonElement("rated")]    public string? Rated { get; set; }    [BsonElement("metacritic")]    public int Metacritic { get; set; }    [BsonElement("plot")]    public string? Plot { get; set; }    [BsonElement("type")]    public string? Type { get; set; }    [BsonElement("cast")]    public string[]? Cast { get; set; }    [BsonElement("directors")]    public string[]? Directors { get; set; }    [BsonElement("writers")]    public string[]? Writers { get; set; }    [BsonElement("imdb")]    public ImdbData? Imdb { get; set; }}To use the MongoDB .NET/C# driver to add a $group stage to an aggregation pipeline, call the UnionWith() method on a PipelineDefinition object.The following example creates a pipeline stage that groups documents by the value of their Rated field. Each group's rating is shown in a field named Rating in each output document. Each output document also contains fields named TotalRuntime, MedianRuntime, and NinetiethPercentileRuntime, which store the total, median, and 90th percentile runtime values for movies in each group.{"@context":"https://schema.org","@type":"SoftwareSourceCode","codeSampleType":"code snippet","text":"var pipeline = new EmptyPipelineDefinition&lt;movie&gt;()
    .Group(
        id: m =&gt; m.Rated,
        group: g =&gt; new
        {
            Rating = g.Key,
            TotalRuntime = g.Sum(m =&gt; m.Runtime),
            MedianRuntime = g.Select(m =&gt; m.Runtime).Median(),
            NinetiethPercentileRuntime =
                g.Select(m =&gt; m.Runtime).Percentile(new[] { 0.9 })
        }
    );

","programmingLanguage":"C#"}var pipeline = new EmptyPipelineDefinition<Movie>()    .Group(        id: m => m.Rated,        group: g => new        {            Rating = g.Key,            TotalRuntime = g.Sum(m => m.Runtime),            MedianRuntime = g.Select(m => m.Runtime).Median(),            NinetiethPercentileRuntime =                g.Select(m => m.Runtime).Percentile(new[] { 0.9 })        }    );VIEW OUTPUT{"@context":"https://schema.org","@type":"SoftwareSourceCode","codeSampleType":"code snippet","text":"{ "Rating" : null, "TotalRuntime" : 967127, "MedianRuntime" : 98.0, "NinetiethPercentileRuntime" : [131.0] }
